import * as Electron from 'electron'
import RendererInterface = Electron.RendererInterface

declare const window: ElectronWindow
export interface ElectronWindow extends Window {
    require(module: string): Electron.RendererInterface
}

const electorn: RendererInterface = window.require('electron')
export default electorn
export const BrowserWindowProxy = electorn.BrowserWindowProxy
export const desktopCapturer = electorn.desktopCapturer
export const ipcRenderer = electorn.ipcRenderer
export const remote = electorn.remote
export const webFrame = electorn.webFrame
export const webViewTag = electorn.webviewTag